[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    /* ─── Design Tokens ──────────────────────────────────────────────── */
    :root {
      --brand-navy:      oklch(22% 0.14 265);
      --brand-navy-mid:  oklch(32% 0.16 265);
      --brand-blue:      oklch(52% 0.22 255);
      --brand-blue-lt:   oklch(62% 0.20 255);
      --brand-yellow:    oklch(88% 0.18 88);
      --brand-yellow-dk: oklch(78% 0.20 80);
      --brand-teal:      oklch(62% 0.18 188);
      --brand-teal-lt:   oklch(72% 0.14 188);
      --bg-white:        oklch(100% 0 0);
      --bg-gray:         oklch(97% 0.005 255);
      --bg-card:         oklch(99% 0.003 255);
      --text-primary:    oklch(18% 0.02 255);
      --text-body:       oklch(38% 0.03 255);
      --text-muted:      oklch(55% 0.03 255);
      --border:          oklch(90% 0.01 255);
      --shadow-sm:       0 1px 3px oklch(0% 0 0 / 0.08), 0 1px 2px oklch(0% 0 0 / 0.04);
      --shadow-md:       0 4px 12px oklch(0% 0 0 / 0.10), 0 2px 4px oklch(0% 0 0 / 0.06);
      --shadow-lg:       0 12px 32px oklch(0% 0 0 / 0.12), 0 4px 8px oklch(0% 0 0 / 0.06);
      --shadow-xl:       0 20px 48px oklch(0% 0 0 / 0.16);
      --radius-sm:       8px;
      --radius-md:       14px;
      --radius-lg:       20px;
      --radius-xl:       28px;
      --radius-full:     9999px;
    }

    /* ─── Reset ──────────────────────────────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
    body {
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      color: var(--text-primary);
      background: var(--bg-white);
      line-height: 1.6;
      overflow-x: hidden;
    }
    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { cursor: pointer; font-family: inherit; }
    ul { list-style: none; }

    /* ─── Utility ────────────────────────────────────────────────────── */
    .container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; }

    /* ─── HEADER ─────────────────────────────────────────────────────── */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: var(--bg-white);
      border-bottom: 1px solid var(--border);
      backdrop-filter: blur(12px);
    }
    .header__inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 68px;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      font-size: 1.35rem;
      letter-spacing: -0.02em;
      color: var(--brand-navy);
    }
    .logo__icon {
      width: 36px;
      height: 36px;
      background: var(--brand-blue);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }
    .logo__icon svg { color: #fff; }
    .logo__dot { color: var(--brand-yellow); }

    .nav {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .nav__link {
      font-size: 0.9rem;
      font-weight: 500;
      color: var(--text-body);
      padding: 8px 14px;
      border-radius: var(--radius-full);
      transition: background 0.18s, color 0.18s;
    }
    .nav__link:hover { background: var(--bg-gray); color: var(--text-primary); }
    .nav__btn {
      font-size: 0.9rem;
      font-weight: 600;
      padding: 9px 20px;
      border-radius: var(--radius-full);
      border: none;
      transition: all 0.18s;
    }
    .nav__btn--outline {
      background: transparent;
      border: 1.5px solid var(--border);
      color: var(--text-primary);
    }
    .nav__btn--outline:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
    .nav__btn--primary {
      background: var(--brand-blue);
      color: #fff;
    }
    .nav__btn--primary:hover { background: var(--brand-navy-mid); }

    /* Hamburger */
    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: 8px;
      background: none;
      border: none;
      border-radius: var(--radius-sm);
      transition: background 0.18s;
    }
    .hamburger:hover { background: var(--bg-gray); }
    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--text-primary);
      border-radius: 2px;
      transition: transform 0.25s, opacity 0.25s;
    }
    .hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.open span:nth-child(2) { opacity: 0; transform: scaleX(0); }
    .hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    /* Mobile drawer */
    .mobile-drawer {
      display: none;
      position: fixed;
      top: 68px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--bg-white);
      z-index: 99;
      padding: 24px;
      flex-direction: column;
      gap: 8px;
      transform: translateX(100%);
      transition: transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .mobile-drawer.open { transform: translateX(0); }
    .mobile-drawer__link {
      font-size: 1.1rem;
      font-weight: 500;
      color: var(--text-body);
      padding: 14px 16px;
      border-radius: var(--radius-md);
      transition: background 0.18s;
      display: block;
    }
    .mobile-drawer__link:hover { background: var(--bg-gray); }
    .mobile-drawer__divider { height: 1px; background: var(--border); margin: 8px 0; }
    .mobile-drawer__btn {
      width: 100%;
      font-size: 1rem;
      font-weight: 600;
      padding: 14px 24px;
      border-radius: var(--radius-full);
      border: none;
      margin-top: 4px;
      transition: all 0.18s;
    }

    /* ─── HERO ───────────────────────────────────────────────────────── */
    .hero {
      position: relative;
      background: linear-gradient(135deg, var(--brand-navy) 0%, var(--brand-navy-mid) 55%, oklch(38% 0.18 255) 100%);
      padding: 96px 0 80px;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 60% 50% at 80% 20%, oklch(62% 0.22 255 / 0.25) 0%, transparent 60%),
        radial-gradient(ellipse 40% 60% at 10% 80%, oklch(88% 0.18 88 / 0.08) 0%, transparent 60%);
      pointer-events: none;
    }
    /* Decorative circles */
    .hero::after {
      content: '';
      position: absolute;
      top: -120px;
      right: -120px;
      width: 500px;
      height: 500px;
      border-radius: 50%;
      border: 1px solid oklch(100% 0 0 / 0.06);
      pointer-events: none;
    }
    .hero__inner { position: relative; z-index: 1; }
    .hero__badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: oklch(100% 0 0 / 0.12);
      border: 1px solid oklch(100% 0 0 / 0.2);
      border-radius: var(--radius-full);
      padding: 6px 16px;
      font-size: 0.82rem;
      font-weight: 600;
      color: oklch(90% 0.05 255);
      letter-spacing: 0.04em;
      text-transform: uppercase;
      margin-bottom: 28px;
      backdrop-filter: blur(8px);
    }
    .hero__badge-dot {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: var(--brand-yellow);
      box-shadow: 0 0 0 3px oklch(88% 0.18 88 / 0.3);
    }
    .hero__title {
      font-size: clamp(2.4rem, 5.5vw, 4rem);
      font-weight: 900;
      line-height: 1.1;
      letter-spacing: -0.04em;
      color: #fff;
      margin-bottom: 20px;
      max-width: 680px;
    }
    .hero__title em {
      font-style: normal;
      color: var(--brand-yellow);
    }
    .hero__subtitle {
      font-size: 1.1rem;
      color: oklch(88% 0.04 255);
      max-width: 560px;
      line-height: 1.65;
      margin-bottom: 48px;
      font-weight: 400;
    }

    /* Search form */
    .search-card {
      background: #fff;
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow-xl);
      padding: 28px;
      max-width: 820px;
    }
    .search-card__label {
      font-size: 0.78rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--text-muted);
      margin-bottom: 10px;
    }
    .search-fields {
      display: grid;
      grid-template-columns: 1fr 1fr 1fr auto;
      gap: 12px;
      align-items: end;
    }
    .search-field {
      display: flex;
      flex-direction: column;
      gap: 6px;
      position: relative;
    }
    .search-field label {
      font-size: 0.78rem;
      font-weight: 600;
      color: var(--text-muted);
      text-transform: uppercase;
      letter-spacing: 0.06em;
    }
    .search-input-wrap {
      position: relative;
      display: flex;
      align-items: center;
    }
    .search-input-wrap .icon {
      position: absolute;
      left: 14px;
      color: var(--text-muted);
      flex-shrink: 0;
      pointer-events: none;
    }
    .search-input {
      width: 100%;
      padding: 13px 14px 13px 42px;
      border: 1.5px solid var(--border);
      border-radius: var(--radius-md);
      font-size: 0.95rem;
      font-family: inherit;
      color: var(--text-primary);
      background: var(--bg-gray);
      outline: none;
      transition: border-color 0.18s, box-shadow 0.18s, background 0.18s;
    }
    .search-input:focus {
      border-color: var(--brand-blue);
      background: #fff;
      box-shadow: 0 0 0 3px oklch(52% 0.22 255 / 0.12);
    }
    .search-input::placeholder { color: var(--text-muted); }
    select.search-input { appearance: none; cursor: pointer; }
    .select-arrow {
      position: absolute;
      right: 12px;
      pointer-events: none;
      color: var(--text-muted);
    }
    .search-btn {
      height: 48px;
      padding: 0 28px;
      background: var(--brand-blue);
      color: #fff;
      font-size: 0.95rem;
      font-weight: 700;
      border: none;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      gap: 8px;
      white-space: nowrap;
      transition: background 0.18s, transform 0.12s, box-shadow 0.18s;
      box-shadow: 0 4px 14px oklch(52% 0.22 255 / 0.35);
    }
    .search-btn:hover {
      background: var(--brand-navy-mid);
      transform: translateY(-1px);
      box-shadow: 0 6px 20px oklch(52% 0.22 255 / 0.45);
    }
    .search-btn:active { transform: translateY(0); }

    /* Autocomplete dropdown */
    .autocomplete-dropdown {
      position: absolute;
      top: calc(100% + 4px);
      left: 0;
      right: 0;
      background: #fff;
      border: 1.5px solid var(--border);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-lg);
      z-index: 50;
      overflow: hidden;
      display: none;
    }
    .autocomplete-dropdown.visible { display: block; }
    .autocomplete-item {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 11px 16px;
      font-size: 0.9rem;
      color: var(--text-body);
      cursor: pointer;
      transition: background 0.14s;
    }
    .autocomplete-item:hover, .autocomplete-item.highlighted {
      background: var(--bg-gray);
      color: var(--brand-blue);
    }
    .autocomplete-item .icon { color: var(--brand-blue); flex-shrink: 0; }

    /* Trust badges below search */
    .hero-trust {
      display: flex;
      align-items: center;
      gap: 24px;
      margin-top: 20px;
      flex-wrap: wrap;
    }
    .hero-trust-item {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 0.82rem;
      font-weight: 500;
      color: oklch(85% 0.04 255);
    }
    .hero-trust-item svg { color: oklch(72% 0.14 188); }

    /* ─── STATS BAR ──────────────────────────────────────────────────── */
    .stats-bar {
      background: var(--brand-navy);
      padding: 36px 0;
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0;
      text-align: center;
    }
    .stat-item {
      padding: 16px 24px;
      position: relative;
    }
    .stat-item + .stat-item::before {
      content: '';
      position: absolute;
      left: 0;
      top: 20%;
      bottom: 20%;
      width: 1px;
      background: oklch(100% 0 0 / 0.12);
    }
    .stat-value {
      font-size: 2rem;
      font-weight: 900;
      letter-spacing: -0.03em;
      color: var(--brand-yellow);
      line-height: 1.1;
      margin-bottom: 6px;
    }
    .stat-label {
      font-size: 0.85rem;
      color: oklch(80% 0.04 255);
      font-weight: 400;
      line-height: 1.4;
    }

    /* ─── SPECIALTIES ────────────────────────────────────────────────── */
    .section {
      padding: 88px 0;
    }
    .section--gray { background: var(--bg-gray); }

    .section-header {
      text-align: center;
      margin-bottom: 56px;
    }
    .section-eyebrow {
      display: inline-block;
      font-size: 0.78rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--brand-blue);
      margin-bottom: 14px;
    }
    .section-title {
      font-size: clamp(1.8rem, 3.5vw, 2.6rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--text-primary);
      line-height: 1.2;
      margin-bottom: 14px;
    }
    .section-subtitle {
      font-size: 1.05rem;
      color: var(--text-body);
      max-width: 540px;
      margin: 0 auto;
    }

    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }
    .specialty-card {
      background: var(--bg-card);
      border: 1.5px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 28px 24px;
      display: flex;
      align-items: flex-start;
      gap: 18px;
      cursor: pointer;
      transition: border-color 0.2s, box-shadow 0.2s, transform 0.2s;
      text-align: left;
    }
    .specialty-card:hover {
      border-color: var(--brand-blue);
      box-shadow: var(--shadow-md);
      transform: translateY(-3px);
    }
    .specialty-icon {
      width: 52px;
      height: 52px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }
    .specialty-card__body { flex: 1; min-width: 0; }
    .specialty-card__name {
      font-size: 1rem;
      font-weight: 700;
      color: var(--text-primary);
      margin-bottom: 6px;
    }
    .specialty-card__desc {
      font-size: 0.85rem;
      color: var(--text-muted);
      line-height: 1.5;
    }
    .specialty-card__arrow {
      align-self: center;
      flex-shrink: 0;
      color: var(--border);
      transition: color 0.18s, transform 0.18s;
    }
    .specialty-card:hover .specialty-card__arrow { color: var(--brand-blue); transform: translateX(4px); }

    /* Specialty icon color pairs */
    .specialty-icon--blue   { background: oklch(52% 0.22 255 / 0.1); color: var(--brand-blue); }
    .specialty-icon--teal   { background: oklch(62% 0.18 188 / 0.1); color: var(--brand-teal); }
    .specialty-icon--yellow { background: oklch(88% 0.18 88  / 0.15); color: var(--brand-yellow-dk); }
    .specialty-icon--purple { background: oklch(55% 0.18 305 / 0.1); color: oklch(55% 0.18 305); }
    .specialty-icon--green  { background: oklch(60% 0.18 155 / 0.1); color: oklch(52% 0.20 155); }
    .specialty-icon--orange { background: oklch(68% 0.20 50  / 0.1); color: oklch(58% 0.20 50); }

    /* ─── HOW IT WORKS ───────────────────────────────────────────────── */
    .steps-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 48px;
      position: relative;
    }
    .steps-grid::before {
      content: '';
      position: absolute;
      top: 36px;
      left: calc(16.67% + 24px);
      right: calc(16.67% + 24px);
      height: 2px;
      background: linear-gradient(90deg, var(--brand-blue), var(--brand-teal));
      border-radius: 2px;
      opacity: 0.35;
    }
    .step {
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      position: relative;
      padding-top: 4px;
    }
    .step__number {
      width: 56px;
      height: 56px;
      border-radius: 50%;
      background: var(--brand-blue);
      color: #fff;
      font-size: 1.1rem;
      font-weight: 800;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 24px;
      box-shadow: 0 4px 14px oklch(52% 0.22 255 / 0.3);
      position: relative;
      z-index: 1;
    }
    .step__title {
      font-size: 1.15rem;
      font-weight: 700;
      color: var(--text-primary);
      margin-bottom: 12px;
      letter-spacing: -0.01em;
    }
    .step__desc {
      font-size: 0.92rem;
      color: var(--text-body);
      line-height: 1.65;
    }

    /* ─── TESTIMONIALS ───────────────────────────────────────────────── */
    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }
    .testimonial-card {
      background: var(--bg-card);
      border: 1.5px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 28px;
      display: flex;
      flex-direction: column;
      gap: 20px;
      transition: box-shadow 0.2s, transform 0.2s;
    }
    .testimonial-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }
    .testimonial-stars {
      display: flex;
      gap: 3px;
    }
    .star { color: var(--brand-yellow-dk); font-size: 1rem; }
    .testimonial-quote {
      font-size: 0.95rem;
      color: var(--text-body);
      line-height: 1.7;
      flex: 1;
      font-style: italic;
    }
    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 14px;
    }
    .author-avatar {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 0.95rem;
      color: #fff;
      flex-shrink: 0;
    }
    .author-name {
      font-size: 0.9rem;
      font-weight: 700;
      color: var(--text-primary);
    }
    .author-location {
      font-size: 0.8rem;
      color: var(--text-muted);
      margin-top: 2px;
    }

    /* ─── MOBILE APP PROMO ───────────────────────────────────────────── */
    .app-promo {
      background: linear-gradient(135deg, var(--brand-navy) 0%, oklch(30% 0.18 255) 100%);
      border-radius: var(--radius-xl);
      padding: 64px 56px;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 48px;
      align-items: center;
      overflow: hidden;
      position: relative;
    }
    .app-promo::before {
      content: '';
      position: absolute;
      right: 0;
      top: 0;
      bottom: 0;
      width: 50%;
      background: radial-gradient(ellipse 80% 100% at 100% 50%, oklch(62% 0.22 255 / 0.2) 0%, transparent 70%);
      pointer-events: none;
    }
    .app-promo__eyebrow {
      font-size: 0.78rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--brand-teal-lt);
      margin-bottom: 14px;
    }
    .app-promo__title {
      font-size: clamp(1.6rem, 3vw, 2.4rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      color: #fff;
      margin-bottom: 14px;
      line-height: 1.15;
    }
    .app-promo__subtitle {
      font-size: 0.98rem;
      color: oklch(82% 0.04 255);
      line-height: 1.65;
      margin-bottom: 32px;
      max-width: 460px;
    }
    .app-features {
      display: flex;
      flex-direction: column;
      gap: 10px;
      margin-bottom: 36px;
    }
    .app-feature {
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 0.88rem;
      color: oklch(85% 0.04 255);
    }
    .app-feature svg { color: var(--brand-teal-lt); flex-shrink: 0; }
    .app-btns {
      display: flex;
      gap: 14px;
      flex-wrap: wrap;
    }
    .app-btn {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      background: oklch(100% 0 0 / 0.1);
      border: 1.5px solid oklch(100% 0 0 / 0.25);
      border-radius: var(--radius-md);
      padding: 12px 20px;
      color: #fff;
      font-size: 0.9rem;
      font-weight: 600;
      transition: background 0.18s, border-color 0.18s;
      backdrop-filter: blur(8px);
    }
    .app-btn:hover { background: oklch(100% 0 0 / 0.18); border-color: oklch(100% 0 0 / 0.4); }
    .app-btn__sub { font-size: 0.72rem; font-weight: 400; opacity: 0.75; display: block; margin-top: 1px; }
    .app-btn__main { font-size: 0.88rem; font-weight: 700; }

    /* Phone mockup */
    .phone-mockup {
      width: 200px;
      flex-shrink: 0;
      position: relative;
      z-index: 1;
    }
    .phone-frame {
      width: 200px;
      height: 360px;
      background: oklch(100% 0 0 / 0.08);
      border: 2px solid oklch(100% 0 0 / 0.2);
      border-radius: 32px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 20px;
      gap: 14px;
      backdrop-filter: blur(8px);
    }
    .phone-screen-item {
      width: 100%;
      background: oklch(100% 0 0 / 0.1);
      border-radius: 10px;
      padding: 12px 14px;
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .phone-dot {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      flex-shrink: 0;
    }
    .phone-lines { flex: 1; display: flex; flex-direction: column; gap: 5px; }
    .phone-line {
      height: 7px;
      border-radius: 4px;
      background: oklch(100% 0 0 / 0.25);
    }
    .phone-line--short { width: 60%; }

    /* ─── FOOTER ─────────────────────────────────────────────────────── */
    .footer {
      background: var(--brand-navy);
      padding: 64px 0 32px;
    }
    .footer__top {
      display: grid;
      grid-template-columns: 260px 1fr;
      gap: 64px;
      margin-bottom: 56px;
    }
    .footer-brand__logo {
      font-size: 1.3rem;
      font-weight: 800;
      color: #fff;
      letter-spacing: -0.02em;
      margin-bottom: 14px;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .footer-brand__logo-icon {
      width: 32px;
      height: 32px;
      background: var(--brand-blue);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .footer-brand__tagline {
      font-size: 0.88rem;
      color: oklch(65% 0.04 255);
      line-height: 1.6;
      margin-bottom: 20px;
    }
    .footer-nav-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
    }
    .footer-col__heading {
      font-size: 0.75rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: oklch(70% 0.05 255);
      margin-bottom: 16px;
    }
    .footer-col__links { display: flex; flex-direction: column; gap: 10px; }
    .footer-col__link {
      font-size: 0.875rem;
      color: oklch(72% 0.04 255);
      transition: color 0.18s;
    }
    .footer-col__link:hover { color: #fff; }
    .footer__bottom {
      border-top: 1px solid oklch(100% 0 0 / 0.1);
      padding-top: 28px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 12px;
    }
    .footer__copy {
      font-size: 0.82rem;
      color: oklch(55% 0.04 255);
    }
    .footer__tagline-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: oklch(100% 0 0 / 0.07);
      border: 1px solid oklch(100% 0 0 / 0.12);
      border-radius: var(--radius-full);
      padding: 4px 12px;
      font-size: 0.78rem;
      color: oklch(75% 0.04 255);
    }
    .footer__tagline-badge svg { color: var(--brand-teal); }

    /* ─── RESPONSIVE ─────────────────────────────────────────────────── */
    @media (max-width: 1024px) {
      .specialties-grid { grid-template-columns: repeat(2, 1fr); }
      .testimonials-grid { grid-template-columns: repeat(2, 1fr); }
      .testimonials-grid > *:last-child { display: none; }
      .app-promo { grid-template-columns: 1fr; }
      .phone-mockup { display: none; }
      .footer__top { grid-template-columns: 1fr; gap: 40px; }
      .footer-nav-grid { grid-template-columns: repeat(2, 1fr); gap: 28px; }
    }

    @media (max-width: 768px) {
      .nav { display: none; }
      .hamburger { display: flex; }
      .mobile-drawer { display: flex; }

      .hero { padding: 60px 0 52px; }
      .hero__title { font-size: 2.2rem; }
      .search-fields {
        grid-template-columns: 1fr;
        gap: 10px;
      }
      .search-card { padding: 20px; border-radius: var(--radius-lg); }
      .search-btn { width: 100%; justify-content: center; height: 50px; }

      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .stat-item + .stat-item::before { display: none; }
      .stat-item:nth-child(2)::before { display: block; }
      .stat-item:nth-child(3)::before {
        display: block;
        top: 0;
        left: 0;
        width: 100%;
        height: 1px;
        bottom: auto;
      }
      .stat-item:nth-child(4)::before {
        display: block;
        top: 0;
        left: 0;
        width: 100%;
        height: 1px;
        bottom: auto;
      }

      .section { padding: 60px 0; }
      .section-header { margin-bottom: 36px; }

      .specialties-grid { grid-template-columns: 1fr; gap: 14px; }

      .steps-grid {
        grid-template-columns: 1fr;
        gap: 36px;
      }
      .steps-grid::before { display: none; }

      .testimonials-grid { grid-template-columns: 1fr; }
      .testimonials-grid > *:last-child { display: flex; }

      .app-promo { padding: 40px 28px; }

      .footer-nav-grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
      .footer__top { gap: 32px; }
      .footer__bottom { flex-direction: column; align-items: flex-start; }
    }

    @media (max-width: 480px) {
      .stats-grid { grid-template-columns: 1fr 1fr; }
      .hero__badge { font-size: 0.72rem; }
      .hero-trust { gap: 14px; }
      .app-btns { flex-direction: column; }
      .app-btn { width: 100%; justify-content: center; }
      .footer-nav-grid { grid-template-columns: 1fr; }
    }

    /* ─── Micro-interactions ─────────────────────────────────────────── */
    @media (prefers-reduced-motion: no-preference) {
      .specialty-card, .testimonial-card, .app-btn, .search-btn, .nav__btn {
        will-change: transform;
      }
    }

    /* Focus styles */
    :focus-visible {
      outline: 2px solid var(--brand-blue);
      outline-offset: 2px;
      border-radius: 4px;
    }
  </style>
</head>
<body>

<!-- ══════════════════════════ HEADER ══════════════════════════════════ -->
<header class="header" role="banner">
  <div class="container">
    <div class="header__inner">
      <!-- Logo -->
