  <div class="mobile-drawer__divider"></div>
  <button class="mobile-drawer__btn nav__btn--outline" style="border:1.5px solid var(--border);background:transparent;color:var(--text-primary);font-family:inherit;font-weight:600;border-radius:var(--radius-full);">Log In</button>
  <button class="mobile-drawer__btn nav__btn--primary" style="background:var(--brand-blue);color:#fff;font-family:inherit;font-weight:600;border-radius:var(--radius-full);">Sign Up — It's Free</button>
</nav>

<!-- ══════════════════════════ HERO ════════════════════════════════════ -->
<section class="hero" aria-label="Hero">
  <div class="container hero__inner">
    <div class="hero__badge">
      <span class="hero__badge-dot" aria-hidden="true"></span>
      Trusted by 4.8M+ patients nationwide
    </div>

    <h1 class="hero__title">
      Find and book the <em>care</em> you need
    </h1>
    <p class="hero__subtitle">
      Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. It's that easy, and always free.
    </p>

    <!-- Search Card -->
    <div class="search-card" role="search" aria-label="Find a doctor">
      <p class="search-card__label">Find care near you</p>
      <div class="search-fields">
        <!-- Field 1: Specialty -->
        <div class="search-field" id="autocomplete-container">
          <label for="search-specialty">Specialty or Doctor</label>
          <div class="search-input-wrap">
            <svg class="icon" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
            <input
              type="text"
              id="search-specialty"
              class="search-input"
              placeholder="Dentist, Back pain, Dr. Sarah Chen…"
              autocomplete="off"
              aria-autocomplete="list"
              aria-controls="autocomplete-dropdown"
              aria-expanded="false"
            />
            <div class="autocomplete-dropdown" id="autocomplete-dropdown" role="listbox" aria-label="Suggestions">
              <!-- Populated by JS -->
            </div>
          </div>
        </div>

        <!-- Field 2: Location -->
        <div class="search-field">
          <label for="search-location">Location</label>
          <div class="search-input-wrap">
            <svg class="icon" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg>
            <input
              type="text"
              id="search-location"
              class="search-input"
              placeholder="City, state, or zip code"
              autocomplete="postal-code"
            />
          </div>
        </div>

        <!-- Field 3: Insurance -->
        <div class="search-field">
          <label for="search-insurance">Insurance</label>
          <div class="search-input-wrap">
            <svg class="icon" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
            <select id="search-insurance" class="search-input" aria-label="Choose your insurance plan">
              <option value="">Choose your plan</option>
              <option>Aetna</option>
              <option>Blue Cross Blue Shield</option>
              <option>Cigna</option>
              <option>Humana</option>
              <option>Kaiser Permanente</option>
              <option>Medicaid</option>
              <option>Medicare</option>
              <option>Oscar Health</option>
              <option>UnitedHealthcare</option>
              <option>No insurance</option>
            </select>
            <svg class="select-arrow" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>
          </div>
        </div>

        <!-- Search button -->
        <button class="search-btn" type="button" aria-label="Search for doctors">
          <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
          Search
        </button>
      </div>
    </div>

    <!-- Trust indicators -->
    <div class="hero-trust" aria-label="Trust indicators">
      <div class="hero-trust-item">
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
        100% free for patients
      </div>
      <div class="hero-trust-item">
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect width="18" height="18" x="3" y="4" rx="2" ry="2"/><line x1="16" x2="16" y1="2" y2="6"/><line x1="8" x2="8" y1="2" y2="6"/><line x1="3" x2="21" y1="10" y2="10"/></svg>
        Same-day appointments available
      </div>
      <div class="hero-trust-item">
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>
        Verified patient reviews
      </div>
    </div>
  </div>
</section>

<!-- ══════════════════════════ STATS BAR ══════════════════════════════ -->
