      <div class="stat-item">
        <dt class="sr-only">Cost</dt>
        <dd class="stat-value">100% Free</dd>
        <div class="stat-label">For patients — always</div>
      </div>
    </dl>
  </div>
</div>

<!-- ══════════════════════════ SPECIALTIES ════════════════════════════ -->
<section class="section" id="specialties" aria-labelledby="specialties-heading">
  <div class="container">
    <header class="section-header">
      <span class="section-eyebrow">Browse by Specialty</span>
