    <ul class="specialties-grid" role="list">

      <li>
        <button class="specialty-card" onclick="handleSpecialty('Primary Care')" aria-label="Browse Primary Care providers">
          <div class="specialty-icon specialty-icon--blue" aria-hidden="true">
