          </div>
          <svg class="specialty-card__arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg>
        </button>
      </li>

      <li>
        <button class="specialty-card" onclick="handleSpecialty('Psychiatrist')" aria-label="Browse Psychiatrist providers">
          <div class="specialty-icon specialty-icon--purple" aria-hidden="true">
            <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2a4 4 0 0 1 4 4c0 1.5-.5 2.8-1.4 3.8L17 22H7l2.4-12.2C8.5 8.8 8 7.5 8 6a4 4 0 0 1 4-4z"/><path d="M9 10h6"/></svg>
          </div>
