          <div class="specialty-card__body">
            <div class="specialty-card__name">Orthopedic Surgeon</div>
            <div class="specialty-card__desc">Joint pain, fractures, and sports injuries</div>
          </div>
          <svg class="specialty-card__arrow" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg>
        </button>
      </li>

    </ul>
  </div>
</section>

<!-- ══════════════════════════ HOW IT WORKS ════════════════════════════ -->
<section class="section section--gray" id="how-it-works" aria-labelledby="hiw-heading">
  <div class="container">
    <header class="section-header">
      <span class="section-eyebrow">How MedBook Works</span>
      <h2 class="section-title" id="hiw-heading">Three steps to your next appointment</h2>
      <p class="section-subtitle">No phone calls. No waiting on hold. Just fast, simple online booking.</p>
    </header>
    <ol class="steps-grid" aria-label="How it works steps">
      <li class="step">
        <div class="step__number" aria-hidden="true">1</div>
        <h3 class="step__title">Search for a provider</h3>
        <p class="step__desc">Enter your specialty, condition, or doctor name along with your location and insurance. Browse detailed provider profiles with photos, credentials, and office hours.</p>
      </li>
      <li class="step">
        <div class="step__number" aria-hidden="true">2</div>
        <h3 class="step__title">Choose a time that works for you</h3>
        <p class="step__desc">View real-time availability and pick an appointment slot that fits your schedule — including same-day and next-day options.</p>
      </li>
